def wall(x1, y1, x2, y2, *, name="Muro", thickness=0.16, height=3.0, color="#3d4652"):
    return {
        "id": f"wall_{int(time.time()*1000)}_{abs(hash((x1, y1, x2, y2, name))) % 999999}",
        "name": name,
        "x1": x1, "y1": y1, "x2": x2, "y2": y2,
        "thickness": thickness,
        "height": height,
        "color": color,
    }
